/**
 * The shape-key port against pytest-coverset: every expected key below is what
 * `pytest_coverset.features.shape_key` returns for the same value written in Python (generated by
 * running the Python plugin; the string kinds are `packages/pytest-coverset/tests/test_features.py`'s).
 * Values that differ by design are tested separately: integral numbers are `int` in JavaScript
 * (`-0`, `1.0`), so `float|integral` never appears.
 */
import { describe, expect, it } from "vitest";

import { lenBucket, shapeKey, stringKind } from "../src/features.js";

const SAME_AS_PYTHON: [string, () => unknown, string][] = [
  ["null", () => null, "NoneType"],
  ["undefined", () => undefined, "NoneType"],
  ["true", () => true, "bool|true"],
  ["false", () => false, "bool|false"],
  ["0", () => 0, "int|zero"],
  ["-3", () => -3, "int|neg"],
  ["2 ** 40", () => 2 ** 40, "int|big|pos"],
  ["2 ** 31 + 1", () => 2 ** 31 + 1, "int|big|pos"],
  ["-(2 ** 31)", () => -(2 ** 31), "int|neg"],
  ["10n", () => 10n, "int|pos"],
  ["NaN", () => NaN, "float|nan"],
  ["Infinity", () => Infinity, "float|inf"],
  ["-Infinity", () => -Infinity, "float|inf|inf-neg"],
  ["2.5", () => 2.5, "float|pos"],
  ["-0.5", () => -0.5, "float|neg"],
  ["\"\"", () => "", "str|empty|len:0"],
  ["\"   \"", () => "   ", "str|len:2-10|whitespace"],
  ["\" x1\"", () => " x1", "str|ascii|digits|len:2-10|ws-edge"],
  ["\"h\u00e9llo\"", () => "héllo", "str|len:2-10|unicode"],
  ["\"x\".repeat(101)", () => "x".repeat(101), "str|ascii|len:101-1000"],
  ["\"x\".repeat(1001)", () => "x".repeat(1001), "str|ascii|len:>1000"],
  ["\"bob@eng.acme.com\"", () => "bob@eng.acme.com", "str|ascii|kind:email/multi-label-domain|len:11-100"],
  ["\"Eve@Example.com\"", () => "Eve@Example.com", "str|ascii|kind:email/uppercase|len:11-100"],
  ["\"1h30m\"", () => "1h30m", "str|ascii|digits|kind:quantity/multi-unit|len:2-10"],
  ["\"2026-10-11\"", () => "2026-10-11", "str|ascii|digits|kind:iso-date|len:2-10"],
  ["\" 42 \"", () => " 42 ", "str|ascii|digits|kind:numeric|len:2-10|ws-edge"],
  ["\"https://example.com/a?b=1\"", () => "https://example.com/a?b=1", "str|ascii|digits|kind:url|len:11-100"],
  ["\"\\u{1F600}\"", () => "\u{1F600}", "str|len:1|unicode"],
  ["new Uint8Array([97, 98, 99])", () => new Uint8Array([97, 98, 99]), "bytes|len:2-10"],
  ["new Uint8Array(0)", () => new Uint8Array(0), "bytes|len:0"],
  ["[]", () => [], "list|len:0"],
  ["[3, -1, 2]", () => [3, -1, 2], "list|any_neg|elem:int|len:2-10|order:unsorted"],
  ["[0, 0]", () => [0, 0], "list|all_zero|any_zero|dups|elem:int|len:2-10|order:sorted|sum_zero"],
  ["[3, 2, 1]", () => [3, 2, 1], "list|elem:int|len:2-10|order:reverse"],
  ["[1, \"a\"]", () => [1, "a"], "list|elem:mixed|len:2-10|order:n/a"],
  ["[1.5, NaN]", () => [1.5, NaN], "list|any_nan|elem:float|len:2-10|order:n/a"],
  ["[1, 2.5]", () => [1, 2.5], "list|elem:mixed|len:2-10|order:sorted"],
  ["[0.1, 0.2, -0.3]", () => [0.1, 0.2, -0.3], "list|any_neg|elem:float|len:2-10|order:unsorted"],
  ["[2, -2]", () => [2, -2], "list|any_neg|elem:int|len:2-10|order:reverse|sum_zero"],
  ["[1.5, Infinity]", () => [1.5, Infinity], "list|any_inf|elem:float|len:2-10|order:sorted"],
  ["[[1, 3], [8, 10], [2, 6]]", () => [[1, 3], [8, 10], [2, 6]], "list|elem:list|len:2-10|order:unsorted|pair:lt"],
  ["[[5, 1]]", () => [[5, 1]], "list|elem:list|len:1|pair:gt"],
  ["[[1, 2], [2, 2]]", () => [[1, 2], [2, 2]], "list|elem:list|len:2-10|order:sorted|pair:mixed"],
  ["[[1, 1], [2, 2]]", () => [[1, 1], [2, 2]], "list|elem:list|len:2-10|order:sorted|pair:eq"],
  ["[[1, 2], [1, 2]]", () => [[1, 2], [1, 2]], "list|dups|elem:list|len:2-10|order:sorted|pair:lt"],
  ["[\"b\", \"a\", \"a\"]", () => ["b", "a", "a"], "list|dups|elem:str|len:2-10|order:reverse"],
  ["[null, null]", () => [null, null], "list|elem:NoneType|len:2-10|order:n/a"],
  ["[true, false]", () => [true, false], "list|elem:bool|len:2-10|order:n/a"],
  ["{ a: 1 }", () => ({ a: 1 }), "dict|elem:int|key:str|len:1"],
  ["{}", () => ({}), "dict|len:0"],
  ["new Map<unknown, unknown>([[1, \"a\"], [\"b\", 2]])", () => new Map<unknown, unknown>([[1, "a"], ["b", 2]]), "dict|elem:mixed|key:mixed|len:2-10"],
  ["new Map()", () => new Map(), "dict|len:0"],
  ["new Set([1, 2])", () => new Set([1, 2]), "set|elem:int|len:2-10"],
  ["new Set()", () => new Set(), "set|len:0"],
  ["Array.from({ length: 40 }, (_, i) => i)", () => Array.from({ length: 40 }, (_, i) => i), "list|any_zero|elem:int|len:11-100|order:sorted"],
];

const STRING_KINDS: [string, string | null][] = [
  ["alice@example.com", "email/plain"],
  ["bob@eng.acme.com", "email/multi-label-domain"],
  ["carol@example.co.uk", "email/plain"],
  ["dave@eng.example.co.uk", "email/multi-label-domain"],
  ["d+tag@x.io", "email/plus-tag"],
  ["Eve@Example.com", "email/uppercase"],
  ["josé@example.com", "email/idn"],
  ["x@xn--bcher-kva.example", "email/idn"],
  ["1h30m", "quantity/multi-unit"],
  ["100ms", "quantity/multi-letter-unit"],
  ["1.5h", "quantity/decimal"],
  ["-5m", "quantity/signed"],
  ["1hx", "quantity/trailing-garbage"],
  ["5m", "quantity/single-unit"],
  ["10 apples", "quantity/multi-letter-unit"],
  ["3 h!", "quantity/trailing-garbage"],
  ["42", "numeric"],
  ["-1.5e3", "numeric"],
  ["2026-10-11", "iso-date"],
  ["2026-10-11T08:00:00Z", "iso-date"],
  ["https://example.com/a?b=1", "url"],
  ["hello world", null],
];

describe("shapeKey", () => {
  it.each(SAME_AS_PYTHON)("%s", (_label, make, key) => {
    expect(shapeKey(make())).toBe(key);
  });

  it("maps integral numbers to int, as the specification says", () => {
    expect(shapeKey(-0)).toBe("int|zero");
    expect(shapeKey(1.0)).toBe("int|pos");
    expect(shapeKey([0.5, -0.5])).toBe("list|any_neg|elem:float|len:2-10|order:reverse|sum_zero");
  });

  it("names class instances by their class, and plain objects as dicts", () => {
    class Money {
      cents = 1;
    }
    expect(shapeKey(new Money())).toBe("obj:Money");
    expect(shapeKey(Object.create(null))).toBe("dict|len:0");
    expect(shapeKey(new Date(0))).toBe("obj:Date");
    expect(shapeKey(() => 1)).toBe("obj:Function");
    expect(shapeKey(Symbol("s"))).toBe("obj:Symbol");
    expect(shapeKey(Buffer.from("abc"))).toBe("bytes|len:2-10");
    expect(shapeKey(new ArrayBuffer(4))).toBe("bytes|len:2-10");
    expect(shapeKey([new Money(), new Money()])).toBe("list|elem:obj:Money|len:2-10|order:n/a");
  });

  it("treats subclasses of builtin containers as objects", () => {
    class Bag extends Array<number> {}
    class Registry extends Map<string, number> {}
    expect(shapeKey(new Bag())).toBe("obj:Bag");
    expect(shapeKey(new Registry())).toBe("obj:Registry");
  });

  it("never runs user code: getters, toString, valueOf, proxies, iterators", () => {
    const calls: string[] = [];
    const record = (name: string) => () => {
      calls.push(name);
      return 1;
    };
    const tricky = { toString: record("toString"), valueOf: record("valueOf") };
    Object.defineProperty(tricky, "lazy", { get: record("getter"), enumerable: true });
    const arr = [1, 2];
    Object.defineProperty(arr, 0, { get: record("index getter") });
    const proxy = new Proxy({}, {
      get: record("proxy get"),
      ownKeys: () => (calls.push("proxy ownKeys"), []),
      getPrototypeOf: () => (calls.push("proxy getPrototypeOf"), Object.prototype),
    });
    const map = new Map([[1, 2]]);
    map[Symbol.iterator] = record("map iterator") as never;
    const set = new Set([1]);
    set.values = record("set values") as never;
    expect(shapeKey(tricky)).toBe("dict|elem:mixed|key:str|len:2-10");
    expect(shapeKey(arr)).toBe("list|elem:mixed|len:2-10|order:n/a");
    expect(shapeKey(proxy)).toBe("obj:Proxy");
    expect(shapeKey(map)).toBe("dict|elem:int|key:int|len:1");
    expect(shapeKey(set)).toBe("set|elem:int|len:1");
    expect(shapeKey([tricky, proxy])).toBe("list|elem:mixed|len:2-10|order:n/a");
    expect(calls).toEqual([]);
  });

  it("summarises at most 32 elements and scans long strings by prefix", () => {
    const long = Array.from({ length: 1000 }, (_, i) => (i < 32 ? 1 : -1));
    expect(shapeKey(long)).toBe("list|dups|elem:int|len:101-1000|order:sorted");
    expect(shapeKey("a".repeat(5000) + " ")).toBe("str|ascii|len:>1000|ws-edge");
  });
});

describe("stringKind", () => {
  it.each(STRING_KINDS)("%s", (text, kind) => {
    expect(stringKind(text)).toBe(kind);
  });
});

it("buckets lengths like pytest-coverset", () => {
  expect([0, 1, 2, 10, 11, 100, 101, 1000, 1001].map(lenBucket)).toEqual([
    "0", "1", "2-10", "2-10", "11-100", "11-100", "101-1000", "101-1000", ">1000",
  ]);
});
